import React from "react";
import { Container, Typography } from "@mui/material";

const Home = () => {
  return (
    <Container style={{ textAlign: "center", marginTop: "20px" }}>
      <Typography variant="h4">Welcome to the SRC E-Voting System</Typography>
      <Typography variant="body1" style={{ marginTop: "10px" }}>
        Vote securely and transparently for your student representatives.
      </Typography>
    </Container>
  );
};

export default Home;
